import React, { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import SignIn from "./components/WorkerSignIn";

function App() {
  const [view, setView] = useState("splash"); 

  return (
    // Base is Lenin Blue to match your Splash screen
    <div className="bg-[#003366] min-h-screen w-full overflow-hidden transition-colors duration-1000">
      <AnimatePresence mode="wait">
        {view === "splash" && (
          <motion.div
            key="splash"
            exit={{ opacity: 0, scale: 0.9, filter: "blur(20px)" }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
          >
            <WorkerSplash onComplete={() => setView("signin")} />
          </motion.div>
        )}

        {view === "signin" && (
          <motion.div
            key="signin"
            initial={{ opacity: 0, y: 100 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            // The Sign-In screen itself will carry the Lemon Yellow background
            className="bg-[#FFF24D] min-h-screen w-full flex items-center justify-center"
          >
            <WorkerSignIn onLogin={() => setView("dashboard")} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
